168	    const turnCounts = (links.get(s.id) ?? []).map((l) => l.turns()).filter((n): n is number => n !== null);
169	    const originalTurns = turnCounts.length ? Math.max(...turnCounts) : null;
170	
171	    const { tag, prompt } = stripTag(s.first_prompt);
172	    tasks.push({
