// Replay eligibility (DESIGN.md §"Plan (coordinator)"): can a recorded task be replayed fairly,
// and on which track? Rules are ordered and short-circuit, so an earlier rule never pays for a probe.

/** Most user prompts a session may have and still be eligible for replay. */
const MAX_PROMPTS = 2;

export interface EligibilityTask {
  userPrompts: number;
  hiddenTests: string[];
  strategy: string;
}

export interface EligibilityProbe {
  installs: boolean;
  suitePasses: boolean;
}

export interface Eligibility {
  eligible: boolean;
  track: "tests" | "judge-only" | "none";
  reason: string;
}

/** Decides replay eligibility for one task; `probe` is called only if no earlier rule already decides. */
export async function checkEligibility(
  task: EligibilityTask,
  probe: () => Promise<EligibilityProbe>,
): Promise<Eligibility> {
  if (task.strategy === "import") {
    return { eligible: false, track: "none", reason: "imported history" };
  }
  if (task.userPrompts > MAX_PROMPTS) {
    return { eligible: false, track: "none", reason: `${task.userPrompts} user prompts (more than ${MAX_PROMPTS})` };
  }

  const { installs, suitePasses } = await probe();
  if (!installs) {
    return { eligible: false, track: "none", reason: "parent does not install" };
  }
  if (!suitePasses) {
    return { eligible: false, track: "none", reason: "parent suite fails" };
  }
  if (task.hiddenTests.length === 0) {
    return { eligible: true, track: "judge-only", reason: "no hidden tests in the original change" };
  }
  return { eligible: true, track: "tests", reason: `${task.hiddenTests.length} hidden test file(s)` };
}

