import { describe, expect, test } from "bun:test";

import { checkEligibility } from "../src/replay/eligibility.ts";

const healthy = async () => ({ installs: true, suitePasses: true });

/** Wraps a probe so the test can assert whether it ran. */
function tracked(probe: () => Promise<{ installs: boolean; suitePasses: boolean }>) {
  const state = { called: false };
  return {
    state,
    probe: async () => {
      state.called = true;
      return probe();
    },
  };
}

describe("checkEligibility", () => {
  test("import strategy is never eligible, on no track, and skips the probe", async () => {
    const p = tracked(healthy);
    const result = await checkEligibility({ userPrompts: 1, hiddenTests: ["a.test.ts"], strategy: "import" }, p.probe);

    expect(result).toEqual({ eligible: false, track: "none", reason: "imported history" });
    expect(p.state.called).toBe(false);
  });

  test("import wins even when later rules would allow the task", async () => {
    const p = tracked(healthy);
    const result = await checkEligibility({ userPrompts: 0, hiddenTests: [], strategy: "import" }, p.probe);

    expect(result.reason).toBe("imported history");
    expect(p.state.called).toBe(false);
  });

  test("more than two user prompts is never eligible and skips the probe", async () => {
    const p = tracked(healthy);
    const result = await checkEligibility({ userPrompts: 3, hiddenTests: ["a.test.ts"], strategy: "normal" }, p.probe);

    expect(result.eligible).toBe(false);
    expect(result.track).toBe("none");
    expect(result.reason.length).toBeGreaterThan(0);
    expect(p.state.called).toBe(false);
  });

  test("two user prompts is still eligible", async () => {
    const result = await checkEligibility({ userPrompts: 2, hiddenTests: ["a.test.ts"], strategy: "normal" }, healthy);
    expect(result).toEqual({ eligible: true, track: "tests", reason: "1 hidden test file(s)" });
  });

  test("a probe that does not install rejects with the parent reason", async () => {
    const p = tracked(async () => ({ installs: false, suitePasses: true }));
    const result = await checkEligibility({ userPrompts: 1, hiddenTests: ["a.test.ts"], strategy: "normal" }, p.probe);

    expect(p.state.called).toBe(true);
    expect(result).toEqual({ eligible: false, track: "none", reason: "parent does not install" });
  });

  test("a parent suite that fails rejects, even with hidden tests", async () => {
    const result = await checkEligibility(
      { userPrompts: 1, hiddenTests: ["a.test.ts"], strategy: "normal" },
      async () => ({ installs: true, suitePasses: false }),
    );

    expect(result.eligible).toBe(false);
    expect(result.track).toBe("none");
    expect(result.reason.length).toBeGreaterThan(0);
  });

  test("no hidden tests routes to the judge-only track", async () => {
    const p = tracked(healthy);
    const result = await checkEligibility({ userPrompts: 1, hiddenTests: [], strategy: "normal" }, p.probe);

    expect(p.state.called).toBe(true);
    expect(result.eligible).toBe(true);
    expect(result.track).toBe("judge-only");
    expect(result.reason.length).toBeGreaterThan(0);
  });

  test("hidden tests with a healthy parent route to the tests track", async () => {
    const result = await checkEligibility(
      { userPrompts: 1, hiddenTests: ["a.test.ts", "b.test.ts"], strategy: "normal" },
      healthy,
    );

    expect(result).toEqual({ eligible: true, track: "tests", reason: "2 hidden test file(s)" });
  });
});

